from pathlib import Path
files={'Web/modern.html': '<section id="aircraft" class="panel hidden"><h2>Flugzeuge in der Umgebung</h2><div class="row"><label>Auswahl<select id="flightMode"><option value="0">Nächstes Flugzeug</option><option value="1">Nähert sich</option></select></label><label>Umkreis (km)<input id="flightRadius" type="number" min="5" max="200" value="50"></label><button onclick="saveFlightSelection()">Übernehmen</button></div>\n<div id="radarPanel"><h2>Flugradar · Wo ist das Flugzeug?</h2><p class="small">Standort in der Mitte · Norden oben · Pfeil zeigt die Bewegung. Auswahl und Verfolgung gelten nur in diesem Safari-Browser.</p><button type="button" onclick="refreshRadar()">Radar aktualisieren</button><p id="radarStatus" role="status">Warte auf SD-Flugdaten</p><div class="radarLayout"><svg id="radarSvg" viewBox="0 0 500 500" role="img" aria-label="Flugradar, Norden oben. Flüge auch über die Flugtafel auswählen."></svg><div><h3>Flugtafel · nächste zuerst</h3><div id="radarList"></div></div></div><section id="radarDetails"><h3 id="radarDetailName">Flug auswählen</h3><button type="button" id="radarPin">Flug verfolgen</button><div id="radarDetailBody"></div><p id="radarRouteStatus" role="status"></p></section></div><details><summary>Nächstes Flugzeug auf dem Gerät</summary><div class="flightHero"><svg id="planeSymbol" class="planeArt" viewBox="0 0 160 200" role="img" aria-label="Flugzeugsymbol"><path fill="white" d="M80 8Q70 12 71 72L12 120V133L72 112V163L48 183V192L80 182L112 192V183L88 163V112L148 133V120L89 72Q90 12 80 8Z"/><circle cx="14" cy="125" r="3" fill="#ff5159"/></svg><svg id="heliSymbol" class="planeArt hidden" viewBox="0 0 160 200" role="img" aria-label="Rotorflugzeug"><path d="M67 99L93 99L84 174H76Z" fill="white"/><rect x="60" y="46" width="40" height="72" rx="18" fill="white"/><rect x="65" y="52" width="30" height="23" rx="10" fill="#00a6ad"/><path d="M8 72L152 90M24 127L136 35M55 168H105" stroke="white" stroke-width="5"/><path d="M49 55V115M111 55V115" stroke="#aaa" stroke-width="4"/><circle cx="80" cy="80" r="7" fill="#bbb"/><circle cx="150" cy="90" r="3" fill="#ff5159"/></svg><svg id="unknownSymbol" class="planeArt hidden" viewBox="0 0 160 200" aria-label="Luftfahrzeugtyp unbekannt"><path d="M80 48L125 100L80 152L35 100Z" fill="none" stroke="white" stroke-width="4"/><text x="80" y="114" fill="white" text-anchor="middle" font-size="40">?</text></svg><div><h2 id="flightName">Warte auf Daten</h2><p id="flightType"></p><p id="flightBearing"></p></div><div id="flightCompass" class="flightCompass"></div></div>\n<div class="metricgrid"><div>Entfernung<strong id="flightDistance">—</strong></div><div>Barometrische Höhe<strong id="flightAltitude">—</strong></div><div>Geschwindigkeit<strong id="flightSpeed">—</strong></div><div>Flugrichtung<strong id="flightTrack">—</strong></div></div><p id="flightStatus" class="flightStatus" role="status"></p><p id="flightRoute" class="flightRoute">Route nicht verfügbar</p><p id="flightRouteNote" class="small">Start / Ziel noch nicht bestätigt.</p><p class="small">Flugdaten: <a href="https://adsb.fi" target="_blank" rel="noreferrer">adsb.fi</a> · private, nicht kommerzielle Nutzung. Unvollständige Empfangsabdeckung möglich. Katalogrouten: <a href="https://www.adsbdb.com" target="_blank" rel="noreferrer">ADSBDB</a>. Keine Bestätigung des heutigen Flugplans.</p></details></section>\n<details id="modernSettings"><summary>Anzeige, Flugzeuge & Gerätename</summary><form id="modernForm"><label>Gerätename<input id="deviceName" maxlength="32" required></label><label class="check"><input type="checkbox" id="aircraftEnabled">Flugzeugansicht aktiv</label><label class="check"><input type="checkbox" id="flightPriority">Himmel als Hauptansicht · Flüge im Umkreis automatisch einblenden</label><label class="check"><input type="checkbox" id="wakeOnFlight">Display bei einem Flug wecken (auch nach manuellem Ausschalten)</label><div class="row"><label>Anzeigedauer (s)<input id="flightDuration" type="number" min="5" max="120" required></label><label>Pause zwischen Einblendungen (s)<input id="flightCooldown" type="number" min="30" max="3600" required></label></div><div class="row"><label>Himmel beim Wechsel (s; 0 = Auto-Intervall)<input id="skyDuration" type="number" min="0" max="600" required></label><label>Flugzeug beim Wechsel (s; 0 = Auto-Intervall)<input id="normalFlightDuration" type="number" min="0" max="600" required></label></div><label>Display nach Inaktivität ausschalten (Minuten; 0 = aus)<input id="sleepMinutes" type="number" min="0" max="240" required></label><button class="primary">Speichern</button></form><p class="small">Menüs bleiben ungestört. Wecken ist separat wählbar. Danach erscheint wieder Himmel; ein zuvor schlafendes Display wird wieder dunkel. Bei Flug-Priorität bleibt der normale automatische Seitenwechsel pausiert. Erste Berührung weckt nur auf.</p><div class="row"><button onclick="act({action:\'wake\'})">DISPLAY WECKEN</button><button onclick="act({action:\'sleep\'})">Display ausschalten</button></div></details>\n<details id="fleet"><summary>Himmel & Flugzeug Geräte <span id="fleetCount"></span></summary><p class="small">Nur WetterHimmel mit kompatibler Firmware. Einträge und Verbindungsschlüssel werden in diesem Safari-Browser gespeichert.</p><div class="row"><button onclick="showPairKey()">Verbindungsschlüssel dieses Geräts anzeigen</button><button onclick="fleetRefresh()">Status prüfen</button></div><p id="pairKey" class="small"></p><form id="fleetForm"><label>Name<input id="fleetName" maxlength="32" required></label><label>Adresse (z. B. http://10.128.0.48)<input id="fleetAddress" required></label><label>Gruppe<input id="fleetGroup" maxlength="32"></label><label>Verbindungsschlüssel<input id="fleetKey" type="password" maxlength="32" required autocomplete="off"></label><label class="check"><input type="checkbox" onchange="$(\'fleetKey\').type=this.checked?\'text\':\'password\'">Schlüssel anzeigen</label><button>Gerät speichern</button></form><div id="fleetList"></div><h3>Ausgewählte Geräte aktualisieren</h3><label>Firmware (.ino.bin)<input id="batchFile" type="file" accept=".bin"></label><label>Prüfdatei aus derselben Version (.json)<input id="batchManifest" type="file" accept=".json"></label><button id="batchStart" class="primary" onclick="batchUpdate()">Aktualisierung starten</button><p id="batchStatus" role="status"></p><p class="small">Mac eingeschaltet und Safari geöffnet lassen. Geräte werden nacheinander aktualisiert. Erfolg erst nach Neustart und Versionsprüfung.</p></details>\n<p><button type="button" onclick="downloadDiagnostic()">Diagnosepaket herunterladen</button><span id="diagnosticStatus" role="status"></span></p>\n\n<dialog id="hangarDialog" aria-labelledby="hangarTitle"><div class="hangarHeader"><h2 id="hangarTitle">Mein Hangar</h2><button id="hangarClose" type="button" onclick="$(\'hangarDialog\').close()">Schließen</button></div><div class="hangarBody"><p class="small">Auf SD gespeicherte Erfassungen im eingestellten Umkreis. Keine Bestätigung einer Sichtbeobachtung. Rückkehr erst nach mindestens 15 Minuten belegter Abwesenheit; bis zu 2 Minuten Sicherheitsabstand. Datenlücken und Neustarts erhöhen den Zähler nicht automatisch.</p><label>ICAO / Registrierung / Rufzeichen<input id="hangarSearch" maxlength="24" placeholder="z. B. HB- oder SWR"></label><label>Sortieren<select id="hangarSort"><option value="last">Zuletzt gesehen</option><option value="passes">Anzahl Überflüge</option></select></label><button onclick="loadHangar(false)">Suchen / Aktualisieren</button><p id="hangarStatus" role="status"></p><div id="hangarRows"></div><button id="hangarNext" disabled onclick="loadHangar(true)">Nächste Seite</button><div id="hangarDetail"></div></div></dialog>\n', 'Web/modern.css': ':root{color:#fff;background:#000;--card:#080808;--line:#777;--ink:#fff;--muted:#ccc;--accent:#00e5dc;--warning:#ffe500;--danger:#ff656c}body{max-width:1200px}button,input,select,dialog,.panel,.weather,#sky,nav,.zoomtools{background:#000!important;color:#fff;border-color:#777}.panel{border:1px solid #777;box-shadow:none;border-radius:14px}button.active,button.primary{background:var(--accent)!important;color:#000!important;border-color:var(--accent)}.error{background:#150708;border:1px solid var(--danger);color:#ffabb0}.small,.sub,#metrics,#feels{color:var(--muted)}a{color:var(--accent)}#mainNav{position:static;flex-wrap:wrap}#mainNav button{min-width:100px}#skyCanvas{max-width:820px!important;width:100%;background:#000}.zoomtools{position:static;justify-content:center}.satgrid{grid-template-columns:repeat(4,1fr)!important}.satcard{background:#000!important;min-height:64px!important;padding:8px}.satcard.above{border-left-color:var(--accent)}#sky.expanded{position:fixed;inset:0;z-index:10;overflow:auto;margin:0;border-radius:0}#sky.expanded canvas{max-height:80vh;width:auto;max-width:100%!important}#sky.expanded #skyExpand{position:sticky;top:0;z-index:11}#sky>h2{font-size:18px}.metricgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metricgrid>div,.flightHero{border:1px solid #777;border-radius:12px;padding:16px}.metricgrid strong{display:block;font-size:26px;margin-top:8px}.flightHero{display:flex;gap:24px;align-items:center}.planeArt{width:180px;height:180px;flex-shrink:0}.flightHero h2{font-size:36px;margin:4px 0}.flightStatus{padding:12px;color:var(--accent)}.flightStatus.stale{color:var(--danger);border-left:3px solid var(--danger)}.hours{display:flex;overflow-x:auto;gap:10px;padding:10px 0}.hours>div{min-width:120px;border:1px solid #666;border-radius:8px;padding:10px}.hours strong{display:block}.fleetrow{border:1px solid #555;border-radius:8px;padding:12px;margin:10px 0}.fleetrow input[type=checkbox]{width:24px;margin-right:10px}.fleetStatus{white-space:pre-wrap;margin:8px 0}.danger{border:1px solid var(--danger)!important;background:#190708!important}.night{--accent:#dd7770;--warning:#d88972;--muted:#b89390;color:#dca5a0;background:#080000}.night .weather,.night .panel,.night nav,.night dialog{background:#080000!important}.night canvas{filter:sepia(1) saturate(3) hue-rotate(315deg) brightness(.6)}.night button.active{background:#b55148!important}.night .hours>div{border-color:#633}.favorite{color:var(--warning)}@media(max-width:650px){.satgrid{grid-template-columns:repeat(2,1fr)!important}.metricgrid{grid-template-columns:repeat(2,1fr)}.flightHero{gap:10px;padding:12px}.flightHero h2{font-size:26px}.planeArt{width:110px;height:140px}#mainNav{gap:4px}#mainNav button{min-width:70px;font-size:14px;padding:10px 6px}body{padding:10px}.metricgrid strong{font-size:22px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n\n.flightCompass{width:200px;max-width:100%;margin-left:auto}.flightCompass svg{width:100%;height:auto}@media(max-width:650px){.flightHero{flex-wrap:wrap}.flightCompass{width:180px;margin:0 auto}}\n\n.planeArt{width:100px;max-height:145px;flex:0 0 100px}.flightHero{gap:20px}.flightHero h2{font-size:1.6rem}\n\n.flightRoute{font-size:clamp(1.25rem,4vw,2rem);font-weight:700;letter-spacing:.04em;color:var(--ink);margin:.7rem 0 .2rem}\n\n#firmwareProgress{appearance:none;-webkit-appearance:none;display:block;width:100%;height:22px;border:1px solid #ff4040;border-radius:6px;background:#171717;margin:16px 0;overflow:hidden}#firmwareProgress::-webkit-progress-bar{background:#171717}#firmwareProgress::-webkit-progress-value{background:#ff3030}#firmwareProgress::-moz-progress-bar{background:#ff3030}#maintenanceStatus{font-size:1.15rem;font-weight:700}\n\n#radarPanel{margin:20px 0} .radarLayout{display:grid;grid-template-columns:minmax(250px,1fr) minmax(260px,1fr);gap:20px}#radarSvg{width:100%;height:auto;aspect-ratio:1;background:#000;touch-action:pan-y}#radarList{max-height:560px;overflow:auto}.radarRow{display:block;width:100%;text-align:left;margin:0 0 10px;padding:14px;min-height:64px}.radarRow span{display:block;margin-top:6px}.radarRow[aria-pressed=true]{border:2px solid #ffe12d}.radarMetrics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.radarMetrics>div{border:1px solid #555;padding:12px;overflow-wrap:anywhere}.radarMetrics strong,.radarMetrics span{display:block}.radarMetrics span{color:#bbb;margin-bottom:8px}#radarDetails{border-top:1px solid #555;margin-top:18px;padding-top:12px}#radarPin{min-height:48px;color:#ffe12d}#radarPanel .stale{color:#ff5159}@media(max-width:700px){.radarLayout{grid-template-columns:1fr}.radarMetrics{grid-template-columns:1fr}#radarList{max-height:420px}}\n\n#hangarDialog{width:760px;background:#000}#hangarDialog .stale{color:#ff5159}#hangarRows{margin-top:16px}#hangarDetail{border-top:1px solid #555;margin-top:16px}\n\n#hangarDialog{padding:0;overflow:hidden;max-height:88vh;max-height:88dvh}#hangarDialog[open]{display:flex;flex-direction:column}.hangarHeader{display:flex;align-items:center;justify-content:space-between;gap:12px;flex:0 0 auto;padding:12px 16px;border-bottom:1px solid #777;background:#000}.hangarHeader h2{margin:0;min-width:0}.hangarHeader button{flex:0 0 auto;min-height:48px}.hangarBody{overflow-y:auto;min-height:0;padding:16px;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}\n', 'WetterHimmel/Modern.h': '#pragma once\n#include "App.h"\n#include "Airframe.h"\n#include "FlightRoute.h"\n#define WW_VERSION "2.0.0-dev8"\nstruct ModernSettings {\n uint32_t version=1;char name[33]="HimmelFlugzeug";\n bool aircraft=true,approaching=false,priority=false,wakeOnFlight=false;\n int radius=50,showSeconds=20,cooldownSeconds=300,sleepMinutes=0;\n int skySeconds=0,flightSeconds=0; // 0 inherits the existing auto interval.\n int favorites[16];int favoriteCount=0;\n};\nstruct Flight {\n bool checked=false,found=false,approaching=false;\n char category[3]={},description[65]={};\n bool rotorcraft=false;\n char callsign[17]={},type[17]={},hex[9]={},error[96]={};\n float distance=NAN,altitude=NAN,speed=NAN,track=NAN,azimuth=NAN;\n time_t received=0,positionAt=0;\n};\nextern ModernSettings modern;\nextern Flight flight;\nextern FlightRoute flightRoute;\nextern bool displayAsleep;\nextern String deviceBoot,deviceKey;\nextern uint32_t renderMaxUs,touchMaxGapMs;\nbool priorityActive();\nvoid modernBegin();void modernTick();void modernState(JsonDocument &d);void modernWeb();\nbool modernCommand(JsonDocument &d,String &error);\nvoid modernJson(JsonObject d,const ModernSettings &m);bool modernRead(JsonVariantConst d,ModernSettings &m);\nvoid wakeDisplay();bool touchSleepGate(bool down);\nvoid manualInteraction();bool flightFresh();\nbool parseFlight(JsonDocument &d,Flight &out,const Place &p,int radius,bool approaching,time_t now);\nvoid modernDiagnostic(JsonDocument &d);\nvoid visiblePassTick();void visiblePassJson(JsonObject d);\nvoid sourceStarted(int kind);void sourceFinished(int kind,int http,uint32_t duration,const char*error,const char*trace);\nvoid sourceJson(JsonObject d);\n\nint automaticNextView();\n', 'Tests/radar_web.cjs': "const {JSDOM,VirtualConsole}=require('jsdom'),fs=require('fs'),assert=require('assert');\nconst fixture=require('./fixtures/state.cjs');fixture.view=2;fixture.modern={name:'Test',aircraft:true,approaching:false,radius:50,favorites:[]};fixture.flight={found:false,checked:true,error:''};fixture.favorites=[];\nlet rev=1,now=1800000000,rows=[{hex:'abcdef',lat:47,lon:7.4,seen_pos:1,track:90,alt_baro:30000,flight:'TEST1',r:'HB-TEST',desc:'<img src=x onerror=evil()>',category:'A3'},{hex:'123456',lat:46.96,lon:7.44,seen_pos:2,alt_baro:1000,track:180,category:'A7'}],conflict=false,busyReplies=10,metaBusy=2;\nconst vc=new VirtualConsole(),errors=[];vc.on('jsdomError',e=>errors.push(e.message));\nfunction response(value){return {ok:true,status:200,text:async()=>JSON.stringify(value),json:async()=>value};}\nconst dom=new JSDOM(fs.readFileSync(__dirname+'/../Web/preview.html','utf8'),{url:'http://192.168.1.48',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(w){w.TextDecoder=TextDecoder;w.TextEncoder=TextEncoder;w.HTMLElement.prototype.scrollIntoView=function(){};w.HTMLCanvasElement.prototype.getContext=()=>new Proxy({measureText:()=>({width:20})},{get:(a,k)=>a[k]||(()=>{})});w.fetch=async(url,opts)=>{const bytes=Buffer.from(JSON.stringify({now,ac:rows}));if(url==='/api/radar'&&metaBusy-->0)return{ok:false,status:503};if(url==='/api/radar')return response({revision:rev,bytes:bytes.length,received:now,now,lat:46.948,lon:7.447,radius:50,boot:'test'});if(url.startsWith('/api/radar?')){if(busyReplies-->0)return{ok:false,status:503};if(conflict)return{ok:false,status:409};const off=+new URL(url,'http://x').searchParams.get('offset'),b=bytes.subarray(off,off+1024);return{ok:true,status:200,arrayBuffer:async()=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)};}if(url==='/api/action')return response({ok:true,view:2});return response(url==='/api/sky'?{stars:[],lines:[],deep:[]}:fixture);};}});\n(async()=>{const w=dom.window,d=w.document;await new Promise(r=>setTimeout(r,100));await w.refreshRadar();for(let i=0;i<200&&d.querySelectorAll('.radarRow').length!==2;i++)await new Promise(r=>setTimeout(r,100));assert(d.querySelector('footer').textContent.includes('2.0.0-dev8'));assert(w.eval('radarTransferClient.retries')>=12);assert.equal(d.querySelectorAll('.radarRow').length,2);assert(d.querySelector('.radarRow').textContent.includes('Helikopter'));\nw.radarSelect('abcdef');d.getElementById('radarPin').click();assert.equal(w.localStorage.getItem('hf-pinned-flight'),'abcdef');assert(d.getElementById('radarDetailBody').textContent.includes('NW'));assert(d.getElementById('radarDetailBody').textContent.includes('O · 90'));assert.equal(d.querySelectorAll('#radarDetailBody img').length,0);\nrows=[rows[1]];rev++;now+=40;await w.refreshRadar();assert(d.getElementById('radarDetailName').textContent.includes('TEST1'));assert(d.getElementById('radarDetailBody').textContent.includes('Kontakt verloren'));assert(d.getElementById('radarDetailBody').textContent.includes('letzte Position'));\nconflict=true;rev++;await w.refreshRadar();assert.equal(d.querySelectorAll('.radarRow').length,1);assert(d.getElementById('radarStatus').textContent.includes('erneut versuchen'));\nconflict=false;rows=[];rev++;now+=100;await w.refreshRadar();assert.equal(d.querySelectorAll('.radarRow').length,0);assert(d.getElementById('radarDetailBody').textContent.includes('Kontakt verloren'));\nmetaBusy=100;await assert.rejects(w.radarRequest('/api/radar','metadata',w.performance.now()+10),/automatisch erneut/);assert.equal(w.eval('radarMeta.revision'),rev);assert.deepEqual(errors,[]);dom.window.close();console.log('PASS radar DOM: list, helicopter, NW vs east, safe text, persistent pin, lost contact, empty result, revision conflict preserves last snapshot');})().catch(e=>{console.error(e);dom.window.close();process.exitCode=1;});\n"}
